import apiClient from './api';

/**
 * Service to manage Gmail integration via server-side OAuth 2.0 authorization code flow.
 * Tokens (refresh & access tokens) are stored securely on the backend database
 * linked with the authenticated Supabase user ID and are NEVER exposed to the browser.
 */
class GmailService {
  /**
   * Fetches Google OAuth 2.0 consent URL generated by the backend with user_id bound in signed state.
   */
  async getAuthUrl() {
    const response = await apiClient.get('/gmail/auth-url');
    return response.data?.auth_url;
  }

  /**
   * Redirects the user's browser to Google's OAuth 2.0 consent screen.
   */
  async redirectToConsentFlow() {
    const authUrl = await this.getAuthUrl();
    if (!authUrl) {
      throw new Error('Could not generate Google authorization URL. Please verify server configuration.');
    }
    window.location.href = authUrl;
  }

  /**
   * Retrieves connection status for the authenticated user from the backend database.
   * @returns {Promise<{ connected: boolean, email?: string, created_at?: string }>}
   */
  async getConnectionStatus() {
    const token = localStorage.getItem('dataraksha_auth_token');
    if (!token) {
      return { connected: false, email: null };
    }
    try {
      const response = await apiClient.get('/gmail/status');
      return response.data;
    } catch (err) {
      // If unauthorized (user not logged in yet), return not connected
      if (err.response?.status === 401) {
        return { connected: false, email: null };
      }
      console.warn('Failed to fetch Gmail connection status:', err);
      return { connected: false, email: null };
    }
  }

  /**
   * Fetches recent inbox emails for the user via backend Gmail REST API proxy.
   * The backend automatically renews expired access tokens using the saved refresh token.
   * @param {number} maxResults
   * @returns {Promise<Array>}
   */
  async fetchRecentInboxEmails(maxResults = 5) {
    const response = await apiClient.get('/gmail/emails', {
      params: { max_results: maxResults },
    });
    return response.data || [];
  }

  /**
   * Analyzes selected email content using Gemini AI and records result to user's private scan history.
   * @param {{ content: string, sender?: string, subject?: string }} payload
   * @returns {Promise<Object>} ScanResultResponse
   */
  async analyzeEmail(payload) {
    const response = await apiClient.post('/gmail/analyze', payload);
    return response.data;
  }

  /**
   * Disconnects user's Gmail account and revokes stored tokens.
   */
  async disconnect() {
    const response = await apiClient.delete('/gmail/disconnect');
    return response.data;
  }
}

export const gmailService = new GmailService();
export default gmailService;
